-- Mois 5 (jours 121 à 150) du programme HABITUDES_DEFIS_30J_FR_V1, version 1 : remplace la reprise des 30 textes du mois 1.
-- Textes validés par Dr Justin Tshims le 27/10/2026 (« C'est bon pour les textes du mois 5 »). Généré depuis
-- editorial/habitudes-defis/mois-5-fr-relecture.md. Aucune inscription n'avait encore atteint le jour 121 : les textes
-- déjà servis (jours 1 à 120) ne changent pas. Activités, défis et horaires inchangés.
do $$begin
 if exists(select 1 from seneve.enrollments e where e.programme_id='HABITUDES_DEFIS_30J_FR_V1' and e.etat='active'
  and seneve.hd_date_du_jour(e.enrollment_id,121)<=(now()at time zone 'Africa/Kinshasa')::date)then
  raise exception 'Une inscription a déjà atteint le jour 121 : publier une nouvelle version plutôt que modifier celle-ci';
 end if;
 if (select count(*)from seneve.contents where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour between 121 and 150 and numero_message=1)<>30 then
  raise exception 'Jours 121 à 150 incomplets';
 end if;
end$$;
update seneve.contents set titre=$t$Relire la semaine : marcher vers la liberté$t$,principe=$t$Faire le point sur la semaine qui ouvre le cinquième mois.$t$,theme=$t$Quel pas vers plus de liberté as-tu fait cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé de regarder ses dettes en face, d'avancer une victoire à la fois, de se libérer du besoin de paraître, de Jésus qui s'est fait pauvre, de l'argent remis à sa place et du travail fait avec Dieu. Relis tes déclarations sans te juger. Remarque un pas, même petit, vers plus de liberté. Un nouveau mois commence : il parlera de compassion et de fidélité.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, page imprimée 78 ; chapitre 4, pages imprimées 92–99 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=121 and numero_message=1;
update seneve.contents set titre=$t$C'est à Lui que tu le fais$t$,principe=$t$Reconnaître Jésus dans la personne dans le besoin.$t$,theme=$t$Qui, autour de toi, a besoin d'être vu aujourd'hui ?$t$,texte_officiel=$t$Au chapitre 5, le livre relit la scène du jugement en Matthieu 25. Le Roi ne demande pas combien de cultes on a fréquentés. Il demande : « Avais-je faim — m'as-tu nourri ? » Puis Il dit : « Toutes les fois que vous avez fait ces choses à l'un de ces plus petits de mes frères, c'est à moi que vous les avez faites » (Matthieu 25:40). Le livre en conclut : « La veuve de ton quartier, c'est Lui. » Aujourd'hui, regarde autour de toi avec ces yeux-là.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 100–102.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=122 and numero_message=1;
update seneve.contents set titre=$t$Une détresse qu'Il connaît$t$,principe=$t$Approcher la souffrance des autres avec le regard de Jésus.$t$,theme=$t$Quelle détresse, proche de toi, aimerais-tu porter dans la prière ?$t$,texte_officiel=$t$Le livre remarque que les questions du Roi décrivent Sa propre vie. Il a eu faim au désert. Enfant, Il a fui en Égypte comme réfugié. Il a été dépouillé au Calvaire et arrêté de nuit. Le livre écrit qu'Il reconnaît les Siens « à une détresse qu'Il a Lui-même habitée ». Pense à une personne qui vit l'une de ces situations : la faim, l'exil, la maladie, la prison. Prie pour elle aujourd'hui, et cherche un geste simple pour la soutenir.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, page imprimée 101.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=123 and numero_message=1;
update seneve.contents set titre=$t$Le coin du champ$t$,principe=$t$Prévoir la part des autres.$t$,theme=$t$Quel coin de ton champ pourrais-tu réserver aux autres ?$t$,texte_officiel=$t$Le livre explique que le mot hébreu Tsedaka signifie justice. La loi d'Israël en donnait une image : on ne moissonnait pas le coin du champ, et l'on laissait des grappes au glaneur (Lévitique 19:9-10). Il résume : « Le champ t'appartient ; le coin du champ appartient au pauvre. » Ce coin peut être un peu d'argent, un peu de temps ou un peu de nourriture. Aujourd'hui, réfléchis au coin que tu pourrais réserver aux autres, à ta mesure.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 102–103.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=124 and numero_message=1;
update seneve.contents set titre=$t$Un cœur pur et des mains ouvertes$t$,principe=$t$Tenir ensemble la sainteté et la compassion.$t$,theme=$t$Entre la pureté du cœur et les mains ouvertes, laquelle demande ton attention ?$t$,texte_officiel=$t$Jacques écrit que la religion pure consiste « à visiter les orphelins et les veuves dans leurs afflictions, et à se préserver des souillures du monde » (Jacques 1:27). Le livre souligne qu'il y a deux dimensions, et que nous séparons souvent ce que Dieu a uni. Il conclut : « La vraie religion tient les deux ensemble : un cœur pur ET des mains ouvertes. » Regarde aujourd'hui laquelle des deux te demande le plus d'attention en ce moment.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 104–105.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=125 and numero_message=1;
update seneve.contents set titre=$t$Mille francs par semaine$t$,principe=$t$Commencer la Tsedaka avec ce que l'on a.$t$,theme=$t$Quelle aide petite mais régulière pourrais-tu offrir ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Nadège, une jeune femme au salaire très modeste, qui a voulu aider Mama Joséphine, veuve avec quatre enfants. Elle a mis de côté mille francs congolais par semaine. Plusieurs mois plus tard, les enfants avaient repris l'école. Le livre conclut : « Elle commence avec ce que tu as, là où tu es, cette semaine. » Ce récit ne fixe aucun montant. Pense à une aide petite mais régulière que tu pourrais offrir.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 105–106.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=126 and numero_message=1;
update seneve.contents set titre=$t$Ce que le monde ne peut pas discuter$t$,principe=$t$Laisser l'amour accompagner la foi.$t$,theme=$t$Quel geste d'amour concret peux-tu poser aujourd'hui ?$t$,texte_officiel=$t$L'apôtre Jean pose une question : « Si quelqu'un possède les biens du monde, et que, voyant son frère dans le besoin, il lui ferme ses entrailles, comment l'amour de Dieu demeure-t-il en lui ? » (1 Jean 3:17). Le livre remarque que la doctrine la plus profonde ne peut pas cohabiter avec un cœur fermé. Il ajoute : « le monde peut discuter tes doctrines — mais il ne peut pas discuter ton amour. » Aujourd'hui, laisse ta foi se voir par un geste d'amour concret.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 107–108.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=127 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : reconnaître le Roi$t$,principe=$t$Faire le point sur la compassion.$t$,theme=$t$Quelle personne as-tu mieux vue cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé du Roi caché dans les plus petits, d'une détresse qu'Il connaît, du coin du champ réservé aux autres, d'un cœur pur et de mains ouvertes, d'une aide modeste et régulière, et d'un amour que personne ne peut discuter. Relis tes déclarations sans te juger. Remarque une personne que tu as mieux vue cette semaine. C'est souvent ainsi que la compassion commence : par un regard.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 100–108 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=128 and numero_message=1;
update seneve.contents set titre=$t$Donner et oublier$t$,principe=$t$Aider sans tenir de registre.$t$,theme=$t$Comment protéger la dignité de la personne que tu aides ?$t$,texte_officiel=$t$Le livre observe qu'aujourd'hui, même la charité devient un contenu : on filme le billet donné, on photographie le sac de riz remis à la veuve. Il rappelle la parole de Jésus sur le don fait en secret (Matthieu 6:3-4), et ajoute : « L'amour véritable donne et oublie. Il ne garde pas de registre de ses bienfaits. » Ne pas exposer quelqu'un dans sa détresse, c'est aussi protéger sa dignité. Aujourd'hui, si tu aides quelqu'un, fais-le sans le raconter.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 108–109.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=129 and numero_message=1;
update seneve.contents set titre=$t$Apprendre son métier à quelqu'un$t$,principe=$t$Donner une compétence.$t$,theme=$t$Quel savoir-faire pourrais-tu transmettre à quelqu'un ?$t$,texte_officiel=$t$Le livre précise que la Tsedaka ne se résume pas à l'argent : « Les compétences sont une monnaie. » Il écrit que le jeune sans formation « a besoin que tu lui apprennes ton métier ». Un savoir-faire partagé peut durer plus longtemps qu'un don. Pense à ce que tu sais faire : lire, compter, cuisiner, réparer, écrire un CV, utiliser un téléphone. Aujourd'hui, propose à quelqu'un de lui apprendre une chose utile.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, page imprimée 111.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=130 and numero_message=1;
update seneve.contents set titre=$t$L'amour qui s'organise$t$,principe=$t$Passer de l'émotion à un engagement dans la durée.$t$,theme=$t$Quelle aide modeste pourrais-tu tenir dans la durée ?$t$,texte_officiel=$t$Le livre remarque qu'on peut donner une fois sous le coup de l'émotion, puis passer à autre chose. Dans Actes 6, quand des veuves étaient oubliées, les apôtres ont organisé l'aide avec sept hommes remplis de l'Esprit. Le livre conclut : « L'émotion passe. L'amour organisé demeure. » Choisis aujourd'hui une forme d'aide que tu peux tenir dans la durée, même modeste, personnellement ou avec ton assemblée.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 112–113.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=131 and numero_message=1;
update seneve.contents set titre=$t$Ému de compassion$t$,principe=$t$Remarquer celui qui ne demande rien.$t$,theme=$t$Qui porte peut-être une peine en silence autour de toi ?$t$,texte_officiel=$t$Aux portes de Naïn, un cortège sort pour enterrer le « fils unique de sa mère, qui était veuve » (Luc 7). Le livre souligne que personne ne demande rien à Jésus. Pourtant, en la voyant, « Il fut ému de compassion pour elle ». Il s'arrête, s'approche et agit. Certaines personnes souffrent sans rien demander. Aujourd'hui, demande à Dieu de t'aider à remarquer quelqu'un qui porte une peine en silence.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, page imprimée 113.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=132 and numero_message=1;
update seneve.contents set titre=$t$Voici ta mère$t$,principe=$t$Faire une place à une personne seule.$t$,theme=$t$Quelle personne seule pourrais-tu inviter davantage dans ta vie ?$t$,texte_officiel=$t$Sur la croix, Jésus voit Sa mère et le disciple qu'Il aime. Il dit : « Femme, voici ton fils. » Puis : « Voici ta mère » (Jean 19:26-27). Le livre remarque : « En train de mourir, le Roi place une veuve dans une famille. » Une personne seule a souvent besoin d'une place plus que d'un don : une invitation, un repas, une visite régulière. Pense à quelqu'un que tu pourrais inclure davantage dans ta vie ou dans ta famille.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, page imprimée 114.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=133 and numero_message=1;
update seneve.contents set titre=$t$Les besoins qu'on ne voit plus$t$,principe=$t$Retrouver un regard neuf sur son entourage.$t$,theme=$t$Quel besoin ne remarquais-tu plus par habitude ?$t$,texte_officiel=$t$La prière du chapitre 5 demande : « Ouvre mes yeux sur les besoins que je ne vois plus par habitude. » Le chapitre se termine ainsi : « Tu cherchais Son visage dans tes prières. Il t'attendait dans le regard de la veuve d'à côté. » Aujourd'hui, sur ton trajet habituel ou dans ta rue, regarde comme si c'était la première fois. Garde dans ton cœur un besoin que tu ne remarquais plus.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 115–116.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=134 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la compassion qui dure$t$,principe=$t$Faire le point sur une compassion discrète et fidèle.$t$,theme=$t$Quel geste de compassion aimerais-tu répéter ?$t$,texte_officiel=$t$Cette semaine a parlé du don qu'on oublie, d'un savoir-faire à transmettre, de l'amour organisé, de Jésus ému devant la veuve de Naïn, d'une place faite à une personne seule et des besoins qu'on ne voit plus. Relis tes déclarations sans te comparer à personne. Remarque un geste que tu pourrais répéter. La compassion la plus utile est souvent celle qui revient, semaine après semaine.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 108–116 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=135 and numero_message=1;
update seneve.contents set titre=$t$Dieu regarde tes habitudes$t$,principe=$t$Voir la fidélité comme un caractère du quotidien.$t$,theme=$t$Quel petit geste de fidélité veux-tu soigner aujourd'hui ?$t$,texte_officiel=$t$Le chapitre 6 commence par une phrase qui rejoint ce parcours : « Dieu n'examine pas tes rêves. Il examine tes habitudes. » Le livre précise que la fidélité n'est pas d'abord une affaire d'argent : « Arriver à l'heure. Tenir sa parole. Finir le travail commencé. » Il cite aussi : rendre l'outil emprunté, ranger les chaises après le culte. Aujourd'hui, choisis un de ces petits gestes et fais-le avec soin.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=136 and numero_message=1;
update seneve.contents set titre=$t$Les mêmes mots pour chacun$t$,principe=$t$Cesser de se comparer.$t$,theme=$t$Avec qui as-tu tendance à te comparer ?$t$,texte_officiel=$t$Dans la parabole des talents, le serviteur qui avait reçu cinq talents et celui qui en avait reçu deux entendent exactement la même parole : « C'est bien, bon et fidèle serviteur ». Le livre en conclut que Dieu « mesure la fidélité dans la gestion », pas la quantité gérée. Tu n'es donc pas en compétition avec celui qui gagne plus que toi. Aujourd'hui, remercie Dieu pour ce qu'Il t'a confié, sans le comparer à ce que d'autres ont reçu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, page imprimée 118.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=137 and numero_message=1;
update seneve.contents set titre=$t$Ce qu'on enterre par peur$t$,principe=$t$Oser utiliser ce que l'on a reçu.$t$,theme=$t$Qu'as-tu enterré par peur ?$t$,texte_officiel=$t$Le troisième serviteur de la parabole a enterré son talent par peur. Le livre souligne qu'il n'a pas été condamné pour avoir peu reçu, « mais pour n'avoir rien fait avec ce qu'il avait reçu ». Un don, une compétence, une idée ou une petite somme peuvent rester enterrés longtemps. Aujourd'hui, nomme une chose que tu gardes cachée par peur, et demande à Dieu le courage d'en faire un premier usage.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, page imprimée 118.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=138 and numero_message=1;
update seneve.contents set titre=$t$Cinquante dollars comme un million$t$,principe=$t$Gérer le peu avec soin.$t$,theme=$t$Quel petit domaine aimerais-tu gérer avec plus de soin ?$t$,texte_officiel=$t$Le livre raconte l'histoire de Dieu-Merci, qui vendait des cacahuètes devant une école avec cinquante dollars de départ. Chaque soir, il notait ses recettes et ses dépenses dans un cahier d'écolier. Ses amis se moquaient de lui. Il disait plus tard : « J'ai appris à gérer cinquante dollars comme si c'était un million. » Le livre ajoute que la promotion « a révélé ce qu'il était déjà ». Regarde aujourd'hui avec quel soin tu gères le peu que tu as.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 120–121.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=139 and numero_message=1;
update seneve.contents set titre=$t$Fidèle en prison$t$,principe=$t$Rester fidèle quand la fidélité ne paie pas.$t$,theme=$t$Où ta fidélité semble-t-elle ne rien rapporter en ce moment ?$t$,texte_officiel=$t$Joseph a été fidèle chez Potiphar, et il a été jeté en prison sur une fausse accusation. Le livre le reconnaît : « la fidélité ne paie pas toujours tout de suite. » En prison, Joseph gère pourtant le cachot comme il gérait la maison (Genèse 39:21-22). Le livre écrit : « Sa fidélité ne dépendait pas de son salaire — elle dépendait de son Dieu. » Si tu traverses une injustice, confie-la à Dieu et garde un geste fidèle aujourd'hui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 121–122.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=140 and numero_message=1;
update seneve.contents set titre=$t$Le jour des petits commencements$t$,principe=$t$Ne pas mépriser son début.$t$,theme=$t$Quel petit commencement as-tu tendance à mépriser ?$t$,texte_officiel=$t$Le prophète Zacharie écrit : « Ne méprise pas le jour des petits commencements » (Zacharie 4:10). Le livre rappelle que Noé, Moïse et David ont connu de longues années discrètes avant leur mission. Il conseille : « ne compare pas ton chapitre 1 avec le chapitre 20 de quelqu'un d'autre. » Tes habitudes de ce parcours sont peut-être, elles aussi, de petits commencements. Aujourd'hui, arrose ta graine sans te comparer.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 122–123.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=141 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : la fidélité dans le peu$t$,principe=$t$Faire le point sur les petites fidélités.$t$,theme=$t$Quelle petite fidélité t'a demandé le plus cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé des habitudes que Dieu regarde, de la comparaison, de ce qu'on enterre par peur, du peu géré avec soin, de la fidélité dans l'injustice et des petits commencements. Relis tes déclarations sans te juger. Ce parcours lui-même est fait de petites fidélités répétées. Remarque celle qui t'a demandé le plus d'effort, et remercie Dieu pour Son aide.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–123 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=142 and numero_message=1;
update seneve.contents set titre=$t$Le registre a deux lecteurs$t$,principe=$t$Être fidèle dans ce que personne ne vérifie.$t$,theme=$t$Quelle tâche, que personne ne vérifie, veux-tu faire entièrement ?$t$,texte_officiel=$t$Le livre raconte l'histoire d'Emmanuel, gardien de nuit. Ses collègues faisaient une ronde sur deux et remplissaient le registre à l'avance. Lui faisait chaque ronde et notait l'heure exacte. Il expliquait : « Le registre a deux lecteurs, frère Justin. Mon chef, qui ne le lit pas. Et mon Dieu, qui le lit toujours. » Pense à une tâche que personne ne contrôle vraiment dans ta vie. Aujourd'hui, fais-la entièrement, pour Dieu.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 123–124.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=143 and numero_message=1;
update seneve.contents set titre=$t$Le désordre n'est pas la foi$t$,principe=$t$Mettre un peu d'ordre dans ses finances.$t$,theme=$t$Dans quel ordre ton argent part-il réellement ?$t$,texte_officiel=$t$Le livre répond à ceux qui disent que le budget n'est pas spirituel : « Le désordre n'est pas de la foi. » Il propose un ordre de priorités : la part de Dieu et l'aide aux pauvres, les besoins essentiels, l'épargne, le remboursement des dettes, puis les désirs et les loisirs. Il remarque que beaucoup vivent cet ordre à l'envers. Si tu le souhaites, écris aujourd'hui ton propre ordre sur un papier qui reste à toi. SÉNEVÉ ne te demande aucun chiffre.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 126–128.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=144 and numero_message=1;
update seneve.contents set titre=$t$Une gestion qui parle$t$,principe=$t$Honorer ses petits engagements d'argent.$t$,theme=$t$Quel petit engagement attend encore d'être tenu ?$t$,texte_officiel=$t$Le livre remarque que Potiphar, le chef de la prison et Pharaon ont vu Dieu dans la gestion de Joseph, sans l'entendre prêcher. Pharaon dit : « Pourrions-nous trouver un homme tel que celui-ci, ayant en lui l'esprit de Dieu ? » (Genèse 41:38). Le livre ajoute que tes collègues observent si tu rembourses les petites sommes empruntées, ou si tu « oublies ». Aujourd'hui, règle une petite dette ou tiens un engagement en attente.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 128–129.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=145 and numero_message=1;
update seneve.contents set titre=$t$La sérénité qui interroge$t$,principe=$t$Laisser sa confiance ouvrir des conversations.$t$,theme=$t$Si quelqu'un te demandait d'où vient ta paix, que répondrais-tu ?$t$,texte_officiel=$t$Le livre raconte l'histoire d'une étudiante en médecine à Chennai, au tout petit revenu, qui donnait régulièrement et avec joie. Sa professeure lui a demandé : « Comment fais-tu pour être si sereine alors que tu n'as presque rien ? » Elle a répondu : « Je donne à Dieu en premier. Et je fais confiance pour le reste. » Cette réponse simple a ouvert une longue conversation. Ta paix peut, elle aussi, parler à ceux qui t'entourent.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 129–130.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=146 and numero_message=1;
update seneve.contents set titre=$t$Sous le figuier$t$,principe=$t$Se savoir vu par Dieu dans la fidélité cachée.$t$,theme=$t$Quelle fidélité cachée aimerais-tu offrir à Dieu aujourd'hui ?$t$,texte_officiel=$t$Jésus dit à Nathanaël : « quand tu étais sous le figuier, je t'ai vu » (Jean 1:48). Le livre explique que le figuier est ici le lieu privé, où personne ne regarde. Il écrit : « Rien de ta fidélité invisible n'a échappé à Ses yeux ». La monnaie rendue exacte, le carnet tenu le soir, la tâche faite avec soin : Dieu les voit. Aujourd'hui, fais un geste fidèle que seul Dieu verra.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 130–131.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=147 and numero_message=1;
update seneve.contents set titre=$t$Entrer dans la joie$t$,principe=$t$Se rappeler le vrai but de la fidélité.$t$,theme=$t$Qu'est-ce qui change si tes habitudes sont un chemin vers Dieu ?$t$,texte_officiel=$t$La parabole des talents se termine par ces mots : « entre dans la joie de ton maître. » Le livre souligne que la récompense finale n'est pas un montant : « C'est Sa joie — c'est Lui. » Il ajoute : « La fidélité dans les petites choses n'est pas une technique de promotion : c'est une longue marche vers ce visage-là. » Aujourd'hui, vis tes habitudes comme un chemin vers Lui, et non comme une performance.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, page imprimée 131.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=148 and numero_message=1;
update seneve.contents set titre=$t$Relire la semaine : vu par Dieu$t$,principe=$t$Faire le point sur la fidélité cachée.$t$,theme=$t$Quelle fidélité cachée retiens-tu de cette semaine ?$t$,texte_officiel=$t$Cette semaine a parlé du registre que Dieu lit toujours, de l'ordre dans l'argent, des petits engagements tenus, d'une paix qui interroge, de Dieu qui voit sous le figuier et de la joie promise aux fidèles. Relis tes déclarations sans te juger. Remarque une fidélité que personne n'a vue, sauf Dieu. Elle compte pour Lui.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 123–131 ; cahier Habitudes & Défis, section 9.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=149 and numero_message=1;
update seneve.contents set titre=$t$Fidèle dans la maison d'un autre$t$,principe=$t$Faire un bilan paisible du mois et choisir un pas.$t$,theme=$t$Quel pas veux-tu garder pour le dernier mois ?$t$,texte_officiel=$t$Le chapitre 6 se termine par cette phrase : « Personne ne monte au trône sans avoir été fidèle dans la maison d'un autre. » Ce mois a parlé de la compassion pour les plus petits et de la fidélité dans le peu. La prière du chapitre demande que la fidélité discrète « devienne mon adoration quotidienne ». Relis tes bilans de semaine et choisis un seul pas pour le dernier mois. Ton bilan ne mesure ni ta foi ni ta valeur.$t$,type_texte='adaptation',reference_livre=$t$Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 132–133.$t$
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and langue='fr' and jour=150 and numero_message=1;
update seneve.programme_versions set valide_par=valide_par||' ; mois 5 (jours 121 à 150) validé le 27/10/2026'
 where programme_id='HABITUDES_DEFIS_30J_FR_V1' and version=1 and valide_par not like '%mois 5%';
